+/* Check if a tvbuff portion complies with the recommendations of RFC 1035 section 2.3.1 */
+static gboolean
+tvb_meets_preferred_name_syntax(tvbuff_t *tvb, const gint offset, const gint length)
+{
+    char c;
+    int i;
+    for (i = offset; i < offset+length; i++) {
+        c = tvb_get_guint8(tvb, i);
+        if ((i == offset && !g_ascii_isalpha(c)) ||
+          ((i+1) == (offset+length) && !g_ascii_isalnum(c)) ||
+          (c != '-' && !g_ascii_isalnum(c))) {
+            return FALSE;
+        }
+    }
+    return TRUE;
+}
